// a2av.cu — replay an unbalanced all-to-all exchange, generated by axccl,
// among the blocks of one cluster.
//
// THE QUESTION
//   In an all-to-all-v ("v" = variable sizes) every rank sends a DIFFERENT
//   number of bytes to every other rank. A 2D-partitioned BFS does exactly
//   this at every level: each block has discovered vertices that other blocks
//   own and must hand them over, and on power-law graphs the amounts are
//   skewed. How long does one such exchange take among the blocks of a
//   cluster, and which way of moving the bytes copes best with the imbalance?
//
// WHERE THE SIZES COME FROM
//   axccl (github.com/HicrestLaboratory/hicrest-axccl) generates unbalanced
//   patterns for MPI collectives: the total each rank sends follows a
//   distribution (HEAVYTAIL, UNIMODALFLAT, ...), the totals are shuffled
//   across ranks, and each total is split across the destinations. Its a2av
//   benchmarks write the whole pattern (the "trace") to
//       logs/<system>/ranks/ALL2ALLV_<DISTRIBUTION>_pairs.log
//   one line per (src_rank, dst_rank) pair and per average message size:
//       nranks,iteration,avg_msgsize,avgoverallbuffersize,src_rank,dst_rank,sendsize,recvsize
//   This program reads that file (--trace) and replays the pattern of one
//   average message size (--avg-msgsize): MPI rank i becomes block i of the
//   cluster, and sendsize(i -> j) becomes the bytes block i delivers into the
//   shared memory of block j. No MPI is involved: the file is only a recipe.
//
// THE METHODS (--method), the same five as transfer.cu
//   Directly from SM to SM through DSMEM:
//     dsmem-push    each block's threads write its messages into the receivers'
//                   shared memory.
//     dsmem-pull    each block's threads read its incoming messages from the
//                   senders' shared memory.
//     dsmem-bulk    the copy engine ("TMA") copies each message; one thread per
//                   destination starts one copy.
//   Through global memory:
//     gmem-ldst     every block copies all its outgoing messages to global
//                   memory, a cluster.sync(), then every block copies its
//                   incoming messages from global memory into shared memory.
//     gmem-tma      the same two copies, done by the copy engine.
//   For reference:
//     cluster-sync  no data: just the barriers that every exchange pays.
//
// ONE EXCHANGE ("round")
//   1. cluster.sync()   every block's outgoing data is ready, and every
//                       receive area is free to be overwritten
//   2. move the bytes   (gmem-*: copy out, cluster.sync(), copy in)
//   3. cluster.sync()   everything has been delivered
//   Time per exchange = the time from 1 to 3, averaged over --rounds rounds.
//   The same barriers with no data (--method cluster-sync) is the floor.
//
//   Why barriers and not one signal per message as in transfer.cu? A signal
//   that announces data needs a "release", ~420 cycles on GB10, and each
//   block would send p - 1 of them per exchange: ~4600 cycles for p = 12,
//   while one cluster.sync() costs ~161 ns (~390 cycles, barriers/barrier.cu)
//   and orders everything.
//
// BUSY TIME
//   Each block also records how long it spent in step 2, i.e. until it
//   reached the final barrier. With an unbalanced pattern the heavy senders
//   arrive last and the others wait for them: max busy / mean busy shows how
//   much of the exchange is imbalance.
//
// CORRECTNESS FIRST
//   As in transfer.cu, one untimed launch fills every message with a pattern
//   that depends on the round, the sender, the receiver and the word, and
//   every receiver checks every word. Any mismatch stops the program.
//
// LIMITS
//   - A block's outgoing AND incoming messages must fit in its shared memory
//     together, so large --avg-msgsize values cannot be replayed: the program
//     says so and stops.
//   - Every message is rounded up to 16 bytes (the unit of the copies and of
//     the copy engine). GB/s counts only the bytes of the trace.
//   - One cluster, so at most 12 ranks on GB10.
//
// Build: make a2av
// Run:   build/a2av --trace ALL2ALLV_HEAVYTAIL_pairs.log --avg-msgsize 1024 --method dsmem-push

#include <cooperative_groups.h>

#include <cstdint>
#include <map>
#include <string>

#include "../common.cuh"   // CUDA_CHECK, Args, globaltimer(), smid(), print_header, ...

namespace cg = cooperative_groups;

enum { DSMEM_PULL, DSMEM_PUSH, DSMEM_BULK, GMEM_LDST, GMEM_TMA, CLUSTER_SYNC };   // --method

constexpr int MAX_RANKS = 16;   // table size; GB10 clusters stop at 12
constexpr int WORD = 16;        // bytes per uint4: the unit every message is counted in

// ------------------------------------------------------------ memory layout

// Shared memory of each block (all blocks use the same layout):
//
//   offset   0   mbarrier: "my incoming copy-engine bytes have landed"
//   offset 128   send area      my outgoing messages, back to back
//   then         receive area   my incoming messages, back to back
//
// Both areas are as large as the largest one over all blocks, so every block
// knows where every other block's areas start.
//
// The messages in each area are in ROTATED order: block b's send area holds
// its message to b first, then to b+1, b+2, ... (mod p); its receive area
// holds the message from b first, then from b+1, ... So at any moment the
// blocks work on different peers instead of all starting with block 0.
constexpr int BARRIER_OFFSET = 0;
constexpr int SEND_OFFSET = 128;

// Where the messages are, in 16-byte words. For block b and k = 0..p-1:
//   out_start[b][k]  where b's message to rank (b + k) % p starts in b's send area
//   in_start[b][k]   where b's message from rank (b + k) % p starts in b's receive area
// and out_start[b][p] / in_start[b][p] is the total, so message k is the
// words [start[k], start[k+1]).
struct Layout {
    int p;                                  // ranks = blocks in the cluster
    int out_start[MAX_RANKS][MAX_RANKS + 1];
    int in_start[MAX_RANKS][MAX_RANKS + 1];
    int send_area_words, recv_area_words;   // the largest totals over all blocks
};

// What went wrong, if anything (managed memory, read by the host).
struct Errors {
    unsigned wrong_words;
    unsigned first_wrong_round, first_wrong_rank, first_wrong_word;
    unsigned timed_out;   // 1 = some wait gave up: a deadlock, not a slow run
};

// Everything the kernel needs, passed by value.
struct Params {
    int method;
    int rounds;            // timed exchanges
    int warmup_rounds;     // untimed exchanges before them
    int verify;            // 1 = fill and check every message (the correctness run)
    Layout layout;
    uint4* staging;        // gmem-*: one send area per rank, in global memory
    unsigned long long* ns;        // the whole run, timed on rank 0
    unsigned long long* busy_ns;   // per rank: total time spent moving bytes
    unsigned* sm_of_rank;
    Errors* errors;
};

// ------------------------------------------------------------ hardware operations
// The same PTX wrappers as transfer.cu, which explains them in more detail.

// My shared memory as a 32-bit shared address (what mbarriers and the copy engine want).
__device__ __forceinline__ uint32_t shared_addr(const void* ptr) {
    return (uint32_t)__cvta_generic_to_shared(ptr);
}
// The same offset in block `rank`'s shared memory, as a cluster address.
__device__ __forceinline__ uint32_t peer_shared_addr(uint32_t my_addr, uint32_t rank) {
    uint32_t r;
    asm volatile("mapa.shared::cluster.u32 %0, %1, %2;" : "=r"(r) : "r"(my_addr), "r"(rank));
    return r;
}
// An mbarrier whose phases complete after `count` arrivals.
__device__ __forceinline__ void barrier_init(uint32_t bar, unsigned count) {
    asm volatile("mbarrier.init.shared::cta.b64 [%0], %1;" ::"r"(bar), "r"(count) : "memory");
}
// Arrive on my own mbarrier and announce `bytes` that the copy engine will
// deliver: the phase completes when both have happened, in either order.
__device__ __forceinline__ void barrier_expect_bytes(uint32_t bar, unsigned bytes) {
    asm volatile("mbarrier.arrive.expect_tx.release.cta.shared::cta.b64 _, [%0], %1;"
                 ::"r"(bar), "r"(bytes) : "memory");
}
// Has the phase with this parity completed? With acquire: the bytes it
// announces are then visible to this thread.
__device__ __forceinline__ bool barrier_phase_done(uint32_t bar, unsigned parity) {
    uint32_t done;
    asm volatile("{\n\t.reg .pred p;\n\t"
                 "mbarrier.try_wait.parity.acquire.cluster.shared::cta.b64 p, [%1], %2;\n\t"
                 "selp.u32 %0, 1, 0, p;\n}"
                 : "=r"(done) : "r"(bar), "r"(parity) : "memory");
    return done;
}
// Copy engine: my shared memory -> a peer's shared memory; completes the peer's mbarrier.
__device__ __forceinline__ void copy_engine_smem_to_peer(uint32_t peer_dst, uint32_t my_src,
                                                         unsigned bytes, uint32_t peer_bar) {
    asm volatile("cp.async.bulk.shared::cluster.shared::cta.mbarrier::complete_tx::bytes "
                 "[%0], [%1], %2, [%3];"
                 ::"r"(peer_dst), "r"(my_src), "r"(bytes), "r"(peer_bar) : "memory");
}
// Copy engine: global memory -> my shared memory; completes my mbarrier.
__device__ __forceinline__ void copy_engine_global_to_smem(uint32_t my_dst, const void* src,
                                                           unsigned bytes, uint32_t my_bar) {
    asm volatile("cp.async.bulk.shared::cluster.global.mbarrier::complete_tx::bytes "
                 "[%0], [%1], %2, [%3];"
                 ::"r"(my_dst), "l"(__cvta_generic_to_global(src)), "r"(bytes), "r"(my_bar)
                 : "memory");
}
// Copy engine: my shared memory -> global memory, and wait until the bytes are written.
__device__ __forceinline__ void copy_engine_smem_to_global_and_wait(void* dst, uint32_t my_src,
                                                                    unsigned bytes) {
    asm volatile("cp.async.bulk.global.shared::cta.bulk_group [%0], [%1], %2;"
                 ::"l"(__cvta_generic_to_global(dst)), "r"(my_src), "r"(bytes) : "memory");
    asm volatile("cp.async.bulk.commit_group;" ::: "memory");
    asm volatile("cp.async.bulk.wait_group 0;" ::: "memory");
}
// Proxy fences: what the threads wrote becomes visible to the copy engine
// (shared memory), or what the copy engine wrote to the threads (global).
__device__ __forceinline__ void fence_threads_to_copy_engine() {
    asm volatile("fence.proxy.async.shared::cta;" ::: "memory");
}
__device__ __forceinline__ void fence_copy_engine_global() {
    asm volatile("fence.proxy.async.global;" ::: "memory");
}

// Wait until cond() is true. After ~2 s (5e9 cycles) give up and tell every
// other waiter to give up too, so a bug ends the run instead of hanging the GPU.
template <class Cond>
__device__ __forceinline__ void wait_until(Cond cond, unsigned* timed_out) {
    const long long start = clock64();
    unsigned tries = 0;
    while (!cond()) {
        if ((++tries & 255) == 0) {
            if (*(volatile unsigned*)timed_out) return;
            if (clock64() - start > 5000000000ll) { atomicExch(timed_out, 1u); return; }
        }
    }
}

// ------------------------------------------------------------ one block's view

// What a block knows about itself and the others. The tables live in shared
// memory: the threads read them in every step of the copy loops.
struct Block {
    int rank, p;
    const int (*out_start)[MAX_RANKS + 1];   // Layout::out_start, in shared memory
    const int (*in_start)[MAX_RANKS + 1];    // Layout::in_start, in shared memory
    uint4* send_area;                        // mine
    uint4* recv_area;                        // mine
    uint32_t my_addr;                        // my shared memory, 32-bit shared address
    const Params* params;

    // The copy plan of the methods whose threads copy (dsmem-push, dsmem-pull
    // and the second half of gmem-ldst). One side of every copy is my own
    // area, where message k is the words [copy_start[k], copy_start[k+1]);
    // the far side of message k starts at far_end[k]: the receiver's receive
    // area (push), or the sender's send area in DSMEM (pull) or in global
    // memory (gmem-ldst). Worked out once, before the first round (see a2av()).
    const int* copy_start;
    uint4* const* far_end;

    // Message from `src` to `dst`: where it starts in src's send area and in
    // dst's receive area. Rank `src` is at position (src - dst) mod p in dst's
    // rotated order, and vice versa.
    __device__ int send_pos(int src, int dst) const { return out_start[src][(dst - src + p) % p]; }
    __device__ int recv_pos(int src, int dst) const { return in_start[dst][(src - dst + p) % p]; }
    // Message k of my send / receive area, in words.
    __device__ int out_words(int k) const { return out_start[rank][k + 1] - out_start[rank][k]; }
    __device__ int in_words(int k) const { return in_start[rank][k + 1] - in_start[rank][k]; }
    __device__ uint4* staging(int r) const {   // rank r's send area in global memory
        return params->staging + (size_t)r * params->layout.send_area_words;
    }
    __device__ uint32_t barrier() const { return my_addr + BARRIER_OFFSET; }
    __device__ unsigned* timed_out() const { return &params->errors->timed_out; }
};

// The loops below walk an area word by word, all threads together, 16 bytes
// per thread per step, regardless of where one message ends and the next
// begins: a 16-byte message and a 60 KiB one keep every thread equally busy.
// `k` is the message the word w belongs to; w only grows, so k only moves
// forward.
__device__ __forceinline__ int message_of(const int* start, int w, int& k) {
    while (w >= start[k + 1]) k++;
    return k;
}

// ------------------------------------------------------------ the methods
//
// The copy loops of push and pull are written so that, word by word, they do
// no more than transfer.cu's block_copy(): one 16-byte load, one 16-byte
// store. Where the far side of a message is (a table in shared memory) is
// looked up only when a thread moves on to the next message, and my own
// area is indexed directly, so the compiler knows it is shared memory and
// uses a shared-memory store or load. (With both sides looked up per word,
// pull and gmem-ldst ran 1.5-4x slower than in transfer.cu.)

// How many 16-byte loads each thread of gather_messages() issues before
// storing them. A read from L2 takes several hundred cycles: one at a time
// per thread leaves most of the bandwidth unused. transfer.cu gets the same
// effect from the compiler, which unrolls its simpler loop 4 times.
constexpr int LOADS_IN_FLIGHT = 4;

// dsmem-pull and the second half of gmem-ldst: my incoming messages, from
// wherever far_end[k] says, into my receive area.
__device__ void gather_messages(const Block& b) {
    const int* start = b.copy_start;
    const int total = start[b.p];
    int k = -1, end = 0;   // the message the thread is in, and where it ends
    const uint4* from = nullptr;
    for (int first = threadIdx.x; first < total; first += LOADS_IN_FLIGHT * blockDim.x) {
        uint4 data[LOADS_IN_FLIGHT];
#pragma unroll
        for (int u = 0; u < LOADS_IN_FLIGHT; u++) {   // all the loads first ...
            const int w = first + u * blockDim.x;
            if (w >= total) break;
            while (w >= end) {   // moved past the end of message k: on to the next one
                k++;
                end = start[k + 1];
                from = b.far_end[k] - start[k];   // so that from[w] is word w of message k
            }
            data[u] = from[w];
        }
#pragma unroll
        for (int u = 0; u < LOADS_IN_FLIGHT; u++) {   // ... then the stores
            const int w = first + u * blockDim.x;
            if (w >= total) break;
            b.recv_area[w] = data[u];
        }
    }
}

// dsmem-push: my outgoing messages, from my send area into the receivers.
__device__ void scatter_messages(const Block& b) {
    const int* start = b.copy_start;
    int k = -1, end = 0;
    uint4* to = nullptr;
    for (int w = threadIdx.x; w < start[b.p]; w += blockDim.x) {
        while (w >= end) {
            k++;
            end = start[k + 1];
            to = b.far_end[k] - start[k];
        }
        to[w] = b.send_area[w];
    }
}

// dsmem-bulk: thread k asks the copy engine to copy my message k into its
// receiver; each receiver waits until all its incoming bytes have landed.
__device__ void bulk_all(const Block& b, int round) {
    if (threadIdx.x == 0)   // "this many bytes are coming to me"
        barrier_expect_bytes(b.barrier(), b.in_start[b.rank][b.p] * WORD);
    const int k = threadIdx.x;
    if (k < b.p && b.out_words(k) > 0) {
        const int dst = (b.rank + k) % b.p;
        const uint32_t peer = peer_shared_addr(b.my_addr, dst);
        const int recv_offset = SEND_OFFSET + b.params->layout.send_area_words * WORD;
        fence_threads_to_copy_engine();   // the engine must see what the threads wrote
        copy_engine_smem_to_peer(peer + recv_offset + b.recv_pos(b.rank, dst) * WORD,
                                 b.my_addr + SEND_OFFSET + b.out_start[b.rank][k] * WORD,
                                 b.out_words(k) * WORD, peer + BARRIER_OFFSET);
    }
    // Every thread waits itself, so every thread may read the data afterwards.
    wait_until([&] { return barrier_phase_done(b.barrier(), round & 1); }, b.timed_out());
}

// gmem-ldst, first half: my whole send area -> my slot of global memory.
__device__ void ldst_copy_out(const Block& b) {
    uint4* out = b.staging(b.rank);
    const int total = b.out_start[b.rank][b.p];   // read once: lets the compiler unroll
    for (int w = threadIdx.x; w < total; w += blockDim.x) out[w] = b.send_area[w];
}
// gmem-tma, first half: one copy-engine copy of my whole send area.
__device__ void tma_copy_out(const Block& b) {
    const int words = b.out_start[b.rank][b.p];
    if (threadIdx.x == 0 && words > 0) {
        fence_threads_to_copy_engine();
        copy_engine_smem_to_global_and_wait(b.staging(b.rank), b.my_addr + SEND_OFFSET,
                                            words * WORD);
        fence_copy_engine_global();   // the engine's writes come before the barrier
    }
}
// gmem-tma, second half: thread k copies my incoming message k.
__device__ void tma_copy_in(const Block& b, int round) {
    if (threadIdx.x == 0)
        barrier_expect_bytes(b.barrier(), b.in_start[b.rank][b.p] * WORD);
    const int k = threadIdx.x;
    if (k < b.p && b.in_words(k) > 0) {
        const int src = (b.rank + k) % b.p;
        const uint32_t recv_offset = SEND_OFFSET + b.params->layout.send_area_words * WORD;
        fence_copy_engine_global();
        copy_engine_global_to_smem(b.my_addr + recv_offset + b.in_start[b.rank][k] * WORD,
                                   b.staging(src) + b.send_pos(src, b.rank), b.in_words(k) * WORD,
                                   b.barrier());
    }
    wait_until([&] { return barrier_phase_done(b.barrier(), round & 1); }, b.timed_out());
}

// Step 2 of one exchange.
__device__ void exchange(const Block& b, cg::cluster_group& cluster, int round) {
    switch (b.params->method) {
        case DSMEM_PUSH: scatter_messages(b); break;
        case DSMEM_PULL: gather_messages(b); break;
        case DSMEM_BULK: bulk_all(b, round); break;
        case GMEM_LDST:  ldst_copy_out(b); cluster.sync(); gather_messages(b); break;
        case GMEM_TMA:   tma_copy_out(b); cluster.sync(); tma_copy_in(b, round); break;
        case CLUSTER_SYNC: break;
    }
}

// ------------------------------------------------------------ verification

// The value of 4-byte word i of the message src -> dst in a given round.
// Different for every (round, src, dst, i) that can occur in one check.
__device__ __forceinline__ unsigned pattern(int round, int src, int dst, int i) {
    return ((unsigned)round * 1000003u) ^ ((unsigned)(src * MAX_RANKS + dst) << 22) ^ (unsigned)i;
}
__device__ void fill_send_area(const Block& b, int round) {
    const int* start = b.out_start[b.rank];
    unsigned* words = (unsigned*)b.send_area;
    int k = 0;
    for (int i = threadIdx.x; i < start[b.p] * 4; i += blockDim.x) {   // 4 x 4 bytes per word
        message_of(start, i / 4, k);
        words[i] = pattern(round, b.rank, (b.rank + k) % b.p, i - start[k] * 4);
    }
}
__device__ void check_recv_area(const Block& b, int round) {
    const int* start = b.in_start[b.rank];
    const unsigned* words = (const unsigned*)b.recv_area;
    Errors* e = b.params->errors;
    int k = 0;
    for (int i = threadIdx.x; i < start[b.p] * 4; i += blockDim.x) {
        message_of(start, i / 4, k);
        if (words[i] != pattern(round, (b.rank + k) % b.p, b.rank, i - start[k] * 4) &&
            atomicAdd(&e->wrong_words, 1u) == 0) {   // the first one to see it records it
            e->first_wrong_round = (unsigned)round;
            e->first_wrong_rank = (unsigned)b.rank;
            e->first_wrong_word = (unsigned)i;
        }
    }
}

// ------------------------------------------------------------ the kernel

// __launch_bounds__(1024): keep the register count low enough for --block-size 1024.
__global__ void __launch_bounds__(1024) a2av(Params params) {
    extern __shared__ __align__(128) unsigned char smem[];
    __shared__ int out_start[MAX_RANKS][MAX_RANKS + 1];
    __shared__ int in_start[MAX_RANKS][MAX_RANKS + 1];
    __shared__ uint4* far_end[MAX_RANKS];

    cg::cluster_group cluster = cg::this_cluster();
    const Layout& layout = params.layout;
    const int rank = (int)cluster.block_rank();
    const int p = layout.p;
    const int recv_offset = SEND_OFFSET + layout.send_area_words * WORD;

    // Copy the tables into shared memory.
    for (int i = threadIdx.x; i < p * (MAX_RANKS + 1); i += blockDim.x) {
        out_start[i / (MAX_RANKS + 1)][i % (MAX_RANKS + 1)] = layout.out_start[0][i];
        in_start[i / (MAX_RANKS + 1)][i % (MAX_RANKS + 1)] = layout.in_start[0][i];
    }
    if (threadIdx.x == 0) {
        barrier_init(shared_addr(smem + BARRIER_OFFSET), 1);   // 1 arrival: my expect_bytes
        // make the initialized mbarrier visible to the other blocks' copy engines
        asm volatile("fence.mbarrier_init.release.cluster;" ::: "memory");
        params.sm_of_rank[rank] = smid();
    }
    __syncthreads();

    Block b;
    b.rank = rank;
    b.p = p;
    b.out_start = out_start;
    b.in_start = in_start;
    b.send_area = (uint4*)(smem + SEND_OFFSET);
    b.recv_area = (uint4*)(smem + recv_offset);
    b.my_addr = shared_addr(smem);
    b.params = &params;
    b.copy_start = (params.method == DSMEM_PUSH) ? out_start[rank] : in_start[rank];
    b.far_end = far_end;

    // The copy plan: thread k works out where the far side of message k is.
    // My own areas go through a plain pointer: a block's message to itself
    // is a local copy, not a trip through DSMEM.
    auto area_of = [&](int r, int offset) {
        return (uint4*)((r == rank ? smem : cluster.map_shared_rank(smem, r)) + offset);
    };
    if (threadIdx.x < p) {
        const int k = threadIdx.x;
        if (params.method == DSMEM_PUSH) {   // my message k -> its receiver's receive area
            const int dst = (rank + k) % p;
            far_end[k] = area_of(dst, recv_offset) + b.recv_pos(rank, dst);
        } else {   // my incoming message k <- its sender's send area, in DSMEM or global memory
            const int src = (rank + k) % p;
            uint4* sender_area = (params.method == GMEM_LDST) ? b.staging(src)
                                                              : area_of(src, SEND_OFFSET);
            far_end[k] = sender_area + b.send_pos(src, rank);
        }
    }
    __syncthreads();

    if (!params.verify) fill_send_area(b, 0);   // defined contents, never checked

    const int total_rounds = params.warmup_rounds + params.rounds;
    unsigned long long t0 = 0, busy = 0;
    for (int round = 0; round < total_rounds; round++) {
        const bool timed = round >= params.warmup_rounds;
        if (params.verify) fill_send_area(b, round);   // "produce" this round's messages
        if (round == params.warmup_rounds) t0 = globaltimer();

        cluster.sync();                     // 1. data ready, receive areas free
        const unsigned long long start = globaltimer();
        exchange(b, cluster, round);        // 2. move the bytes
        __syncthreads();                    //    the whole block is done
        if (timed) busy += globaltimer() - start;
        cluster.sync();                     // 3. everything delivered

        if (params.verify) check_recv_area(b, round);   // "consume" them
    }
    const unsigned long long t1 = globaltimer();

    if (threadIdx.x == 0) {
        params.busy_ns[rank] = busy;
        if (rank == 0) *params.ns = t1 - t0;
    }
    // A block's shared memory disappears when it exits: nobody leaves while
    // another block might still be reading it.
    cluster.sync();
}

// ------------------------------------------------------------ host: the trace

// One average message size of an axccl *_pairs.log: bytes[src][dst].
struct Pattern {
    int p = 0;
    std::vector<std::vector<long long>> bytes;
};

// Split a CSV line at the commas.
static std::vector<std::string> split_csv(const std::string& line) {
    std::vector<std::string> fields;
    size_t from = 0;
    for (size_t comma; (comma = line.find(',', from)) != std::string::npos; from = comma + 1)
        fields.push_back(line.substr(from, comma - from));
    fields.push_back(line.substr(from));
    return fields;
}

// Read the pattern of one average message size. Exits with a message (listing
// the sizes the file does have) if anything is missing.
static Pattern read_trace(const char* path, size_t avg_msgsize) {
    FILE* f = fopen(path, "r");
    if (!f) { fprintf(stderr, "a2av: cannot open --trace %s\n", path); exit(1); }

    std::map<std::string, int> column;   // column name -> index
    std::map<size_t, int> lines_per_size;
    Pattern pat;
    char buf[1024];
    while (fgets(buf, sizeof buf, f)) {
        std::string line(buf);
        while (!line.empty() && (line.back() == '\n' || line.back() == '\r')) line.pop_back();
        if (line.empty() || line[0] == '#') continue;
        std::vector<std::string> fields = split_csv(line);
        if (column.empty()) {   // the header
            for (size_t i = 0; i < fields.size(); i++) column[fields[i]] = (int)i;
            for (const char* name : {"nranks", "avg_msgsize", "src_rank", "dst_rank", "sendsize"})
                if (!column.count(name)) {
                    fprintf(stderr, "a2av: %s has no column %s: not an axccl *_pairs.log?\n",
                            path, name);
                    exit(1);
                }
            continue;
        }
        const size_t size = strtoull(fields[column["avg_msgsize"]].c_str(), nullptr, 10);
        lines_per_size[size]++;
        if (size != avg_msgsize) continue;
        const int p = atoi(fields[column["nranks"]].c_str());
        if (pat.p == 0) {
            pat.p = p;
            pat.bytes.assign(p, std::vector<long long>(p, -1));   // -1 = not seen yet
        }
        const int src = atoi(fields[column["src_rank"]].c_str());
        const int dst = atoi(fields[column["dst_rank"]].c_str());
        if (p != pat.p || src < 0 || src >= p || dst < 0 || dst >= p || pat.bytes[src][dst] >= 0) {
            fprintf(stderr, "a2av: %s: bad or repeated line for avg_msgsize %zu: %s\n", path,
                    avg_msgsize, line.c_str());
            exit(1);
        }
        pat.bytes[src][dst] = strtoll(fields[column["sendsize"]].c_str(), nullptr, 10);
    }
    fclose(f);

    if (pat.p == 0) {
        fprintf(stderr, "a2av: %s has no lines for --avg-msgsize %zu. It has:", path, avg_msgsize);
        for (auto& [size, n] : lines_per_size) fprintf(stderr, " %zu", size);
        fprintf(stderr, "\n");
        exit(1);
    }
    for (int i = 0; i < pat.p; i++)
        for (int j = 0; j < pat.p; j++)
            if (pat.bytes[i][j] < 0) {
                fprintf(stderr, "a2av: %s: no line for %d -> %d\n", path, i, j);
                exit(1);
            }
    return pat;
}

// The distribution name in an axccl file name: ALL2ALLV_HEAVYTAIL_pairs.log -> HEAVYTAIL.
static std::string distribution_of(const char* path) {
    std::string name(path);
    name = name.substr(name.find_last_of('/') + 1);
    const size_t first = name.find('_'), last = name.rfind("_pairs");
    if (first == std::string::npos || last == std::string::npos || last <= first) return "unknown";
    return name.substr(first + 1, last - first - 1);
}

// Turn the byte counts into the rotated layout (see Layout).
static Layout make_layout(const Pattern& pat) {
    Layout l = {};
    const int p = pat.p;
    l.p = p;
    auto words = [&](int src, int dst) { return (int)((pat.bytes[src][dst] + WORD - 1) / WORD); };
    for (int b = 0; b < p; b++) {
        for (int k = 0; k < p; k++) {
            l.out_start[b][k + 1] = l.out_start[b][k] + words(b, (b + k) % p);
            l.in_start[b][k + 1] = l.in_start[b][k] + words((b + k) % p, b);
        }
        l.send_area_words = std::max(l.send_area_words, l.out_start[b][p]);
        l.recv_area_words = std::max(l.recv_area_words, l.in_start[b][p]);
    }
    return l;
}

// ------------------------------------------------------------ host: main

int main(int argc, char** argv) {
    Args a;
    a.method = DSMEM_PUSH;
    parse_args(argc, argv, &a, "a2av",
               "  --trace FILE      axccl ALL2ALLV_<DIST>_pairs.log to replay   (required)\n"
               "  --avg-msgsize N   which of its average message sizes          (required)\n"
               "  --method M        dsmem-push | dsmem-pull | dsmem-bulk | gmem-ldst |\n"
               "                    gmem-tma | cluster-sync              (default dsmem-push)\n"
               "  --rounds N        exchanges per repetition             (default 1000)\n"
               "  --warmup N        untimed passes of --rounds exchanges (default 1)\n"
               "  --block-size N    threads per block                    (default 128)\n");
    if (!a.trace) { fprintf(stderr, "a2av: --trace is required (try --help)\n"); return 1; }
    if (a.block_size < 32 || a.block_size > 1024 || a.block_size % 32) {
        fprintf(stderr, "a2av: --block-size must be a multiple of 32, 32..1024\n");
        return 1;
    }
    if (a.rounds < 1) { fprintf(stderr, "a2av: --rounds must be >= 1\n"); return 1; }

    // ---- the pattern
    const Pattern pat = read_trace(a.trace, a.avg_msgsize);
    const int p = pat.p;
    if (p < 2 || p > 12) {
        fprintf(stderr, "a2av: the trace has %d ranks; one cluster holds 2..12 blocks\n", p);
        return 1;
    }
    if (a.block_size < p) {   // bulk and tma start one copy per thread
        fprintf(stderr, "a2av: --block-size must be at least the %d ranks\n", p);
        return 1;
    }
    const Layout layout = make_layout(pat);
    std::vector<long long> sent(p, 0), received(p, 0);
    long long total_bytes = 0;
    for (int i = 0; i < p; i++)
        for (int j = 0; j < p; j++) {
            sent[i] += pat.bytes[i][j];
            received[j] += pat.bytes[i][j];
            total_bytes += pat.bytes[i][j];
        }
    const long long max_sent = *std::max_element(sent.begin(), sent.end());
    const long long max_received = *std::max_element(received.begin(), received.end());

    // ---- shared memory: barrier + send area + receive area
    int max_smem = 0;
    CUDA_CHECK(cudaDeviceGetAttribute(&max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, 0));
    const int static_smem = (int)(2 * sizeof(int) * MAX_RANKS * (MAX_RANKS + 1) +
                                  2 * sizeof(void*) * MAX_RANKS);
    const long long smem_bytes =
        SEND_OFFSET + (long long)(layout.send_area_words + layout.recv_area_words) * WORD;
    if (smem_bytes + static_smem > max_smem) {
        fprintf(stderr,
                "a2av: avg_msgsize %zu needs %lld B of shared memory per block (largest send area "
                "%d B + largest receive area %d B), only %d B fit: try a smaller --avg-msgsize\n",
                a.avg_msgsize, smem_bytes, layout.send_area_words * WORD,
                layout.recv_area_words * WORD, max_smem - static_smem);
        return 1;
    }

    const std::string dist = distribution_of(a.trace);
    char extra[600];
    snprintf(extra, sizeof extra,
             "# trace: %s\n# distribution: %s\n# avg_msgsize: %zu\n# nranks: %d\n"
             "# method: %s\n# rounds: %d\n# total_bytes: %lld\n# max_sent_bytes: %lld\n"
             "# max_received_bytes: %lld\n# dynamic_smem_bytes: %lld\n",
             a.trace, dist.c_str(), a.avg_msgsize, p, TRANSFER_METHOD[a.method], a.rounds,
             total_bytes, max_sent, max_received, smem_bytes);
    print_header(argc, argv, a, 0, extra,
                 "benchmark,method,distribution,nranks,avg_msgsize,total_bytes,max_sent_bytes,"
                 "max_received_bytes,block_size,rounds,seed,rep,ns,ns_per_exchange,gbps,"
                 "busy_max_ns,busy_mean_ns\n");

    // ---- memory the kernel needs
    Params params = {};
    params.method = a.method;
    params.layout = layout;
    const size_t staging_bytes = (size_t)p * std::max(layout.send_area_words, 1) * WORD;
    CUDA_CHECK(cudaMalloc(&params.staging, staging_bytes));
    CUDA_CHECK(cudaMemset(params.staging, 0, staging_bytes));
    CUDA_CHECK(cudaMallocManaged(&params.ns, sizeof(unsigned long long)));
    CUDA_CHECK(cudaMallocManaged(&params.busy_ns, p * sizeof(unsigned long long)));
    CUDA_CHECK(cudaMallocManaged(&params.sm_of_rank, p * sizeof(unsigned)));
    CUDA_CHECK(cudaMallocManaged(&params.errors, sizeof(Errors)));

    // ---- launch configuration: one cluster of p blocks
    CUDA_CHECK(cudaFuncSetAttribute((const void*)a2av,
                                    cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes));
    if (p > 8) allow_big_clusters((const void*)a2av);
    cudaLaunchConfig_t cfg = {};
    cfg.gridDim = dim3(p);
    cfg.blockDim = dim3(a.block_size);
    cfg.dynamicSmemBytes = (size_t)smem_bytes;
    cudaLaunchAttribute attr;
    attr.id = cudaLaunchAttributeClusterDimension;
    attr.val.clusterDim.x = p;
    attr.val.clusterDim.y = 1;
    attr.val.clusterDim.z = 1;
    cfg.attrs = &attr;
    cfg.numAttrs = 1;

    auto launch = [&](int rounds, int warmup_rounds, int verify) {
        params.rounds = rounds;
        params.warmup_rounds = warmup_rounds;
        params.verify = verify;
        *params.errors = Errors{};
        CUDA_CHECK(cudaLaunchKernelEx(&cfg, a2av, params));
        CUDA_CHECK(cudaDeviceSynchronize());
        if (params.errors->timed_out) {
            fprintf(stderr, "a2av: %s timed out (deadlock?)\n", TRANSFER_METHOD[a.method]);
            exit(1);
        }
    };

    // ---- 1. correctness: every message filled and checked (cluster-sync moves nothing)
    if (a.method != CLUSTER_SYNC) launch(std::min(a.rounds, 64), 0, 1);
    if (params.errors->wrong_words) {
        fprintf(stderr, "a2av: %s: %u WRONG words, first in round %u, rank %u, word %u\n",
                TRANSFER_METHOD[a.method], params.errors->wrong_words,
                params.errors->first_wrong_round, params.errors->first_wrong_rank,
                params.errors->first_wrong_word);
        return 1;
    }

    // ---- 2. timing: one CSV row per repetition
    std::vector<double> ns_per_exchange, gbps, imbalance;
    for (int rep = 0; rep < a.reps; rep++) {
        launch(a.rounds, a.warmup * a.rounds, 0);
        const double ns = (double)*params.ns / a.rounds;
        const double g = (a.method == CLUSTER_SYNC) ? 0 : total_bytes / ns;   // bytes per ns = GB/s
        double busy_max = 0, busy_sum = 0;
        for (int r = 0; r < p; r++) {
            const double busy = (double)params.busy_ns[r] / a.rounds;
            busy_max = std::max(busy_max, busy);
            busy_sum += busy;
        }
        printf("a2av,%s,%s,%d,%zu,%lld,%lld,%lld,%d,%d,%d,%d,%llu,%.3f,%.4f,%.3f,%.3f\n",
               TRANSFER_METHOD[a.method], dist.c_str(), p, a.avg_msgsize, total_bytes, max_sent,
               max_received, a.block_size, a.rounds, a.seed, rep, *params.ns, ns, g, busy_max,
               busy_sum / p);
        ns_per_exchange.push_back(ns);
        gbps.push_back(g);
        imbalance.push_back(busy_max / (busy_sum / p));
    }

    // ---- human-readable summary on stderr
    fprintf(stderr, "a2av %s, %s, %d ranks, avg_msgsize %zu: %lld B per exchange, verified\n",
            TRANSFER_METHOD[a.method], dist.c_str(), p, a.avg_msgsize, total_bytes);
    fprintf(stderr, "  rank |  SM | sends (B) | receives (B) | busy ns (last rep)\n");
    for (int r = 0; r < p; r++)
        fprintf(stderr, "  %4d | %3u | %9lld | %12lld | %8.0f\n", r, params.sm_of_rank[r], sent[r],
                received[r], (double)params.busy_ns[r] / a.rounds);
    print_stats_line("ns per exchange", ns_per_exchange);
    print_stats_line("GB/s", gbps);
    print_stats_line("busy max/mean", imbalance);

    CUDA_CHECK(cudaFree(params.staging));
    CUDA_CHECK(cudaFree(params.ns));
    CUDA_CHECK(cudaFree(params.busy_ns));
    CUDA_CHECK(cudaFree(params.sm_of_rank));
    CUDA_CHECK(cudaFree(params.errors));
    return 0;
}
